    std::vector<std::vector<std::string>> nested = {{"a", "b"}, {"c", "d"}};
    nlohmann::json j = std::move(nested);
    std::cout << "json: " << j.dump() << std::endl;
    std::cout << "nested[0][0] size: " << nested[0][0].size() << std::endl;
    return 0;
